import React, { useState } from 'react';
import { Plus, Trash2, List } from 'lucide-react';

const ExtraPointsList = ({ extraPoints, setExtraPoints }) => {
  const [newPoint, setNewPoint] = useState('');

  const addExtraPoint = () => {
    if (newPoint.trim() !== '') {
      setExtraPoints([...extraPoints, newPoint.trim()]);
      setNewPoint('');
    }
  };

  const removeExtraPoint = (index) => {
    setExtraPoints(extraPoints.filter((_, i) => i !== index));
  };

  const updateExtraPoint = (index, value) => {
    const updated = extraPoints.map((point, i) => i === index ? value : point);
    setExtraPoints(updated);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addExtraPoint();
    }
  };

  // Predefined common energy audit points
  const commonPoints = [
    'Comprehensive assessment of electrical systems, motors, and drives',
    'Thermal imaging analysis for heat loss identification',
    'Power quality analysis and harmonics study',
    'Compressed air system optimization study',
    'Lighting system energy efficiency evaluation',
    'HVAC system performance assessment',
    'Steam and boiler efficiency analysis',
    'Renewable energy integration feasibility study',
    'Energy monitoring and management system recommendations',
    'Carbon footprint assessment and reduction strategies',
    'Detailed financial analysis with NPV and IRR calculations',
    'Benchmarking against industry best practices'
  ];

  const addCommonPoint = (point) => {
    if (!extraPoints.includes(point)) {
      setExtraPoints([...extraPoints, point]);
    }
  };

  return (
    <section>
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-medium text-gray-900 flex items-center gap-2">
          <List className="h-5 w-5" />
          Extra Points / Scope of Work
        </h3>
        <span className="text-sm text-gray-500">
          {extraPoints.length} point{extraPoints.length !== 1 ? 's' : ''}
        </span>
      </div>

      {/* Add New Point */}
      <div className="flex items-center gap-3 mb-4">
        <input
          type="text"
          value={newPoint}
          onChange={(e) => setNewPoint(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder="Add a new scope point..."
          className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
        />
        <button
          type="button"
          onClick={addExtraPoint}
          disabled={!newPoint.trim()}
          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Plus className="h-4 w-4" />
          Add
        </button>
      </div>

      {/* Common Points Suggestions */}
      {extraPoints.length === 0 && (
        <div className="mb-6 p-4 bg-blue-50 rounded-md border border-blue-200">
          <h4 className="text-sm font-medium text-blue-900 mb-3">
            Quick Add - Common Energy Audit Points:
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {commonPoints.slice(0, 6).map((point, index) => (
              <button
                key={index}
                type="button"
                onClick={() => addCommonPoint(point)}
                className="text-left px-3 py-2 text-sm bg-white text-blue-700 rounded border border-blue-300 hover:bg-blue-100 transition-colors"
              >
                + {point}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Current Points List */}
      {extraPoints.length > 0 && (
        <div className="space-y-3">
          {extraPoints.map((point, index) => (
            <div key={index} className="flex items-start gap-3 p-3 bg-gray-50 rounded-md border border-gray-200">
              <div className="flex-shrink-0 w-6 h-6 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-sm font-medium mt-1">
                {index + 1}
              </div>
              <textarea
                value={point}
                onChange={(e) => updateExtraPoint(index, e.target.value)}
                className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 resize-none"
                rows="2"
              />
              <button
                type="button"
                onClick={() => removeExtraPoint(index)}
                className="flex-shrink-0 p-1 text-red-600 hover:bg-red-50 rounded"
              >
                <Trash2 className="h-4 w-4" />
              </button>
            </div>
          ))}
        </div>
      )}

      {extraPoints.length === 0 && (
        <div className="text-center py-8 text-gray-500">
          <List className="h-8 w-8 mx-auto mb-2 text-gray-400" />
          <p>No extra points added yet.</p>
          <p className="text-sm">Add specific scope items or project deliverables above.</p>
        </div>
      )}
    </section>
  );
};

export default ExtraPointsList;
